function parse(raw: string): ChartNote[] {
  const notes: ChartNote[] = [];
  for (const entry of raw.split(";")) {
    const sep = entry.indexOf(",");
    notes.push({
      beat: Number(entry.slice(0, sep)) / 1000,
      lane: Number(entry.slice(sep + 1)),
      kind: "tap",
    });
  }
  return notes;
}

